442 |             | Self::IncompatibleTransaction { backtrace, .. }
443 |             | Self::RetryableCommitConflict { backtrace, .. }
444 |             | Self::TooMuchWriteContention { backtrace, .. }
445 |             | Self::Internal { backtrace, .. }
